import { expect, test } from "@playwright/test";

import { parseDotEnv } from "./env";

// Runs without a browser or the stack: it checks how the helpers read the
// .env files dev-setup writes.
test.describe("support env", () => {
  test("parses dev-setup output", () => {
    const values = parseDotEnv(
      [
        "# Generated by scripts/dev-setup.sh",
        "CALBOOKER_PUBLIC_URL=http://host.example:8083",
        "CALBOOKER_BROWSER_CLIENT_NAME='Calbooker (development)'",
        'QUOTED="two words"',
        "export EXPORTED=yes",
        "",
      ].join("\n"),
    );
    expect(values).toEqual({
      CALBOOKER_PUBLIC_URL: "http://host.example:8083",
      CALBOOKER_BROWSER_CLIENT_NAME: "Calbooker (development)",
      QUOTED: "two words",
      EXPORTED: "yes",
    });
  });

  test("ignores comments and malformed lines", () => {
    const values = parseDotEnv("# KEY=comment\nnot a setting\n1BAD=x\n=empty\nGOOD=a=b\nOPEN='unterminated\n");
    expect(values).toEqual({ GOOD: "a=b", OPEN: "'unterminated" });
  });
});
